#include <cstdint>
#include <utility>
#include <vector>

class SparseVector {
  std::vector<std::pair<int, int>> nz_;       // (index, value), sorted by index, non-zeros only
public:
  explicit SparseVector(const std::vector<int>& nums) {
    for (int i = 0; i < (int)nums.size(); ++i)
      if (nums[i] != 0) nz_.emplace_back(i, nums[i]);
  }

  // Two pointers over both sorted lists: O(k1 + k2) time, no hashing.
  int64_t dotProduct(const SparseVector& o) const {
    int64_t sum = 0;
    size_t i = 0, j = 0;
    while (i < nz_.size() && j < o.nz_.size()) {
      if (nz_[i].first == o.nz_[j].first)
        sum += int64_t(nz_[i++].second) * o.nz_[j++].second;
      else if (nz_[i].first < o.nz_[j].first) ++i;
      else ++j;
    }
    return sum;
  }
};

