int myAtoi(const std::string& s) {
  size_t i = 0, n = s.size();
  while (i < n && s[i] == ' ') ++i;                 // 1. leading spaces
  int sign = 1;
  if (i < n && (s[i] == '+' || s[i] == '-'))        // 2. at most one sign
    sign = (s[i++] == '-') ? -1 : 1;
  int result = 0;
  while (i < n && s[i] >= '0' && s[i] <= '9') {     // 3. digits until the first non-digit
    int d = s[i++] - '0';
    // 4. check BEFORE multiplying: result * 10 + d must stay <= INT_MAX
    if (result > (INT_MAX - d) / 10)
      return sign == 1 ? INT_MAX : INT_MIN;
    result = result * 10 + d;
  }
  return sign * result;
}

