def is_v4_part(p: str) -> bool:
    if not 1 <= len(p) <= 3 or not all("0" <= c <= "9" for c in p):
        return False                     # ASCII digits only: str.isdigit() accepts '²' etc.
    if len(p) > 1 and p[0] == "0":
