    ++top;
    for (int r = top; r <= bottom; ++r) out.push_back(m[r][right]);
    --right;
    for (int c = right; c >= left; --c) out.push_back(m[bottom][c]);
    --bottom;
    for (int r = bottom; r >= top; --r) out.push_back(m[r][left]);
    ++left;
  }
  return out;
}

