std::vector<int> spiralOrder(const std::vector<std::vector<int>>& m) {
  std::vector<int> out;
  if (m.empty()) return out;
  int top = 0, bottom = (int)m.size() - 1, left = 0, right = (int)m[0].size() - 1;
  while (top <= bottom && left <= right) {
    for (int c = left; c <= right; ++c) out.push_back(m[top][c]);      // right along the top
    ++top;
    for (int r = top; r <= bottom; ++r) out.push_back(m[r][right]);    // down the right side
    --right;
    if (top <= bottom) {                                               // a row is still left
      for (int c = right; c >= left; --c) out.push_back(m[bottom][c]); // left along the bottom
      --bottom;
    }
    if (left <= right) {                                               // a column is still left
      for (int r = bottom; r >= top; --r) out.push_back(m[r][left]);   // up the left side
      ++left;
    }
  }
  return out;
}

