// Rotate an n x n matrix 90 degrees clockwise, in place.
// Clockwise = transpose, then reverse every row.
void rotate(std::vector<std::vector<int>>& m) {
  const int n = m.size();
  for (int i = 0; i < n; ++i)
    for (int j = i + 1; j < n; ++j)          // j > i: swap each pair exactly once
      std::swap(m[i][j], m[j][i]);
  for (auto& row : m) std::reverse(row.begin(), row.end());
}

