int compress(std::vector<char>& chars) {
    int n = (int)chars.size(), w = 0, i = 0;
    while (i < n) {
        int j = i;
        while (j < n && chars[j] == chars[i]) j++;   // [i, j) is one group
        chars[w++] = chars[i];
        if (j - i > 1)
            for (char d : std::to_string(j - i)) chars[w++] = d;
        i = j;
    }
    return w;
}

long long trap(const std::vector<int>& h) {
    int l = 0, r = (int)h.size() - 1;
    int leftMax = 0, rightMax = 0;
    long long water = 0;
    while (l < r) {
        if (h[l] < h[r]) {
            leftMax = std::max(leftMax, h[l]);
            water += leftMax - h[l];
            l++;
        } else {
            rightMax = std::max(rightMax, h[r]);
            water += rightMax - h[r];
            r--;
        }
    }
    return water;
}

