from bisect import bisect_left
from collections import defaultdict

def is_subsequence(s, t):
    i = 0
    for c in t:
        if i < len(s) and s[i] == c:
            i += 1
    return i == len(s)

class SubseqChecker:
    def __init__(self, t):
        self.pos = defaultdict(list)          # char -> sorted indices in t
        for i, c in enumerate(t):
            self.pos[c].append(i)

    def check(self, s):
        cur = 0                               # first index of t still usable
        for c in s:
            lst = self.pos.get(c)
            if not lst:
                return False
            k = bisect_left(lst, cur)
            if k == len(lst):
                return False
            cur = lst[k] + 1
        return True

